export function effectiveRetention(settings) {
  if (settings.retentionDays !== undefined) return settings.retentionDays;
  if (settings.workspaceTier === 'managed') return 90;
  return 30;
}

export function mayDelete(actor, record) {
  return actor.role === 'owner' && record.locked !== true;
}
